WITH filtered AS (SELECT *, ROUND(units, 2) AS units_rounded FROM store_sales WHERE sale_date >= DATE '2023-08-07') SELECT dim.region, dim.city, COUNT(*) AS rows_total, SUM(src.revenue) AS total_revenue, SUM(src.units_rounded) AS total_units_rounded, GROUPING_ID() AS level_id FROM filtered src JOIN stores dim ON src.store_id = dim.id GROUP BY ROLLUP (dim.region, dim.city) ORDER BY region DESC
